import{_ as s}from"./chunks/local-review.CIdXSg-u.js";import{_ as i,o as t,c as a,a2 as n}from"./chunks/framework.B3-dzFNu.js";const r="/projects/redline/diagrams/rpc-lifecycle.svg",E=JSON.parse('{"title":"Stdio JSON-RPC protocol","description":"","frontmatter":{},"headers":[],"relativePath":"stdio-protocol.md","filePath":"stdio-protocol.md","lastUpdated":1793496711000}'),o={name:"stdio-protocol.md"};function d(l,e,h,p,c,k){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="stdio-json-rpc-protocol" tabindex="-1">Stdio JSON-RPC protocol <a class="header-anchor" href="#stdio-json-rpc-protocol" aria-label="Permalink to &quot;Stdio JSON-RPC protocol&quot;">​</a></h1><p>Use <code>redline rpc</code> when a program needs to start, query or cancel a local Git review. It is a transport over the same execution path as <code>redline review</code>. It does not implement LSP, HTTP, an editor extension, a public TypeScript SDK or forge publication.</p><h2 id="visual-overview" tabindex="-1">Visual overview <a class="header-anchor" href="#visual-overview" aria-label="Permalink to &quot;Visual overview&quot;">​</a></h2><p><a href="./diagrams/local-review.html" target="_self"><img src="'+s+'" alt="A client program sends stdio requests to the RPC adapter. The RPC adapter and terminal CLI share capture, review, validation and artifact writing."></a></p><p><a href="./diagrams/local-review.html" target="_self">Explore the shared review architecture</a>. Open the interactive view to zoom, select components and inspect source references. Editor extensions remain planned; the reference client is implemented.</p><p><a href="./diagrams/rpc-lifecycle.html" target="_self"><img src="'+r+`" alt="An accepted run starts as running and ends as completed, incomplete, failed, cancelled or timed-out."></a></p><p><a href="./diagrams/rpc-lifecycle.html" target="_self">Explore the RPC run lifecycle</a>. A completed run can contain findings. Only a whole-run deadline produces <code>timed-out</code>; a file timeout can leave incomplete coverage. Cancellation remains cooperative, and completion can win the race.</p><p>These local diagrams use <a href="https://tt-a1i.github.io/archify/" target="_blank" rel="noreferrer">Archify</a>. Their <a href="/projects/redline/diagrams/README">sources and regeneration instructions</a> pin the generator and the reviewed code revision. The written contract below remains the reference.</p><h2 id="start-the-process" tabindex="-1">Start the process <a class="header-anchor" href="#start-the-process" aria-label="Permalink to &quot;Start the process&quot;">​</a></h2><p>Use Node.js 24 and the installed Redline command. The installed version must include <code>redline rpc</code>; version 1.0.0 predates this command. For an updated source checkout, replace <code>redline</code> with <code>node /path/to/redline/bin/redline.mjs</code>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rpc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rpc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --indexing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disabled</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rpc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --once</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --indexing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disabled</span></span></code></pre></div><p>The last two commands wait for framed requests on stdin. They do not start a review by themselves. <code>echo</code> tests integration without a model or credentials. It always returns a clean answer and does not establish code quality.</p><p>For a real model, configure the existing <a href="/projects/redline/get-started/configuration">private user configuration</a>. Selecting Pi or OpenCode can send captured source to the configured provider and incur model charges. Trusted startup flags can select the harness, model, endpoint, budgets, indexing and reuse. The server reads that fixed configuration path and inherited settings for each review. Repository selection still rechecks that the configuration file and executables are outside the reviewed repository. Existing output defaults also apply. Omit a fixed output directory from persistent-session configuration because every review needs a new directory.</p><p>The startup <code>--auth</code> option accepts only <code>none</code>, the non-secret credential-less endpoint mode. It does not accept a key or token. Credentials come from the trusted configuration file or <code>REDLINE_MODEL_AUTH</code>; the RPC server passes startup options to its in-memory configuration parser. It does not forward <code>--auth</code> to a harness command line.</p><p>No credential values, configuration paths, executable paths, model endpoints, output paths or reporter selection are accepted in protocol requests. Keep credentials out of command-line values too. Reviewed content never selects configuration or executes code.</p><p>Stdout contains protocol frames only. Stderr is reserved for startup diagnostics and runtime warnings. Clients must drain both streams.</p><h2 id="frame-messages" tabindex="-1">Frame messages <a class="header-anchor" href="#frame-messages" aria-label="Permalink to &quot;Frame messages&quot;">​</a></h2><p>Each JSON-RPC 2.0 object is UTF-8 JSON preceded by exactly one ASCII header:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Length: &lt;UTF-8 byte count&gt;\\r\\n</span></span>
<span class="line"><span>\\r\\n</span></span>
<span class="line"><span>&lt;JSON body&gt;</span></span></code></pre></div><p>Here <code>\\r\\n</code> means the two actual CR/LF bytes, not literal backslashes. Do not append an extra newline after the body. Headers are case-insensitive but must use the shown single-space format. Additional headers, duplicate lengths, leading-zero lengths, non-ASCII headers, zero-length bodies and oversized frames are rejected.</p><p>This uses a common stdio framing convention, not LSP method semantics. JSON-RPC&#39;s <code>jsonrpc: &quot;2.0&quot;</code> field is distinct from Redline&#39;s protocol version <code>&quot;1.0&quot;</code>.</p><p>Request IDs are strings of at most 128 Unicode characters or safe integers. ID zero is valid. Null IDs are not accepted. Methods below require IDs. The only defined client notification is <code>redline/v1/exit</code>; other client notifications are ignored without a response.</p><p>Batches contain 1 to 16 messages, processed in array order. Notification-only batches have no response. Duplicate request IDs in a batch are rejected before any batch method runs. If a batch&#39;s combined response would exceed the message limit, the server replaces its largest result replies with limit errors until the batch fits. Small acknowledgements for already-accepted start, cancel and shutdown operations remain intact. Query a rejected result individually instead of repeating the operation.</p><h2 id="initialize-and-negotiate" tabindex="-1">Initialize and negotiate <a class="header-anchor" href="#initialize-and-negotiate" aria-label="Permalink to &quot;Initialize and negotiate&quot;">​</a></h2><p>Send this before starting reviews:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redline/v1/initialize&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;protocolVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;optionalCapabilities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;progress&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}}</span></span></code></pre></div><p>The result contains the selected protocol version, capabilities and actual limits. The current server supports version <code>1.0</code>. A higher minor request within major 1 selects <code>1.0</code>; an unsupported major returns a version error. Initialize only once per process.</p><p><code>git</code>, <code>cancel</code>, <code>artifacts</code>, <code>pagination</code> and <code>batch</code> are supported. <code>progress</code> is optional and enabled when the optional-capability list is absent or contains it. Unknown IDs in that optional list are ignored. Unknown parameter fields are rejected.</p><p>Additive compatible changes use a protocol minor version. Breaking fields or semantics require a new major namespace. Clients must use the selected version&#39;s schema rather than assuming future fields exist.</p><h2 id="start-a-review" tabindex="-1">Start a review <a class="header-anchor" href="#start-a-review" aria-label="Permalink to &quot;Start a review&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redline/v1/review.start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;repository&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/absolute/path/to/project&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;base&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;head&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HEAD&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;comparison&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;merge-base&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>For a working-tree review:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redline/v1/review.start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;repository&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/absolute/path/to/project&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;worktree&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;staged&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>The repository must be an absolute path on the server&#39;s host. <code>base</code> defaults to <code>HEAD</code>. A supplied <code>head</code> selects committed review, with <code>comparison</code> defaulting to <code>merge-base</code>; <code>direct</code> is also supported. Without <code>head</code>, <code>worktree</code> defaults to <code>all</code> and accepts <code>staged</code> or <code>unstaged</code>. <code>untracked</code> defaults to <code>exclude</code>; <code>include</code> requires a compatible working-tree mode. Repository/target semantics and source limits remain those of the <a href="/projects/redline/local-cli">CLI</a>.</p><p>The server returns a generated <code>runId</code> and a running descriptor immediately. Configuration, revision or execution failures can then finish that accepted run with a structured error. Protocol-invalid requests never reach the review engine.</p><p>Only one review runs per process. Additional starts receive a busy error, not an implicit queue. Existing per-file concurrency, retries, deadlines, reasoning behavior and private result reuse are unchanged.</p><h2 id="query-and-cancel" tabindex="-1">Query and cancel <a class="header-anchor" href="#query-and-cancel" aria-label="Permalink to &quot;Query and cancel&quot;">​</a></h2><p>Use the returned <code>runId</code> in these calls. Replace the example UUID with that actual value.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redline/v1/review.get&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;runId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;00000000-0000-0000-0000-000000000000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redline/v1/review.cancel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;runId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;00000000-0000-0000-0000-000000000000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>Descriptors contain state, exit code, a bounded error or null, artifact references when available, result availability and progress counts. States are <code>running</code>, <code>completed</code>, <code>incomplete</code>, <code>failed</code>, <code>cancelled</code> and <code>timed-out</code>. Completion can still contain findings; coverage and exit code remain separate.</p><p>Cancellation aborts pending work through the existing process/worker controls. The acknowledgement can still show <code>running</code> while children stop and artifacts settle. Wait for terminal state. If completion wins the race, it remains completed. Cancelling a terminal run does not change it. Exactly one finished notification is produced for an accepted run while output remains writable.</p><h2 id="consume-notifications-and-results" tabindex="-1">Consume notifications and results <a class="header-anchor" href="#consume-notifications-and-results" aria-label="Permalink to &quot;Consume notifications and results&quot;">​</a></h2><ul><li><code>redline/v1/artifacts</code> supplies a run descriptor as soon as the private output directory exists. Retain its references for crash recovery.</li><li><code>redline/v1/progress</code> supplies <code>runId</code>, a monotonic sequence and metadata-only events. Updates are coalesced at 100 ms intervals, with a final flush before terminal state, and may be dropped under backpressure. Counts track required, settled and active files. Settled files can include omissions and are not proof of successful coverage. Retries can move files back to active.</li><li><code>redline/v1/finished</code> supplies the terminal descriptor.</li></ul><p>Progress never includes source paths, source payloads, prompts, raw model text, reasoning or credentials. Validated result pages can contain source evidence, suggestions and deterministic fix prompts. Redline redacts selected credentials without changing other evidence whitespace.</p><p>After terminal state, request a page:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redline/v1/review.result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;runId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;00000000-0000-0000-0000-000000000000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;section&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;findings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;offset&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>Sections are <code>overview</code>, <code>files</code> and <code>findings</code>, with <code>overview</code> as the default. Responses contain <code>total</code>, <code>items</code> and <code>nextOffset</code>. A null next offset means the section is exhausted. Smaller pages can be returned to fit the byte limit.</p><p>The overview includes verdict, required/completed/omitted/excluded coverage, context status, finding count and limitations. File entries include outcome and structured diagnostics. Findings include authoritative locations and evidence, classification, severity, confidence, supporting evidence, root cause, impact, verification/remediation status, guidance, suggestion and fix prompt. Diff/structure validation is not proof that the model&#39;s diagnosis or proposed fix is correct. These are validated review projections, not raw model records. Paths and finding text are still untrusted display data. Render them as text, and never execute suggestions automatically.</p><p>A run that exceeds result-retention limits can complete with <code>resultAvailable: false</code>. Querying that result, or a single item too large for one frame, returns a limit error. Use the written artifact references instead. No finding is silently removed to pretend coverage is complete.</p><h2 id="limits-and-backpressure" tabindex="-1">Limits and backpressure <a class="header-anchor" href="#limits-and-backpressure" aria-label="Permalink to &quot;Limits and backpressure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Limit</th></tr></thead><tbody><tr><td>Header including delimiter</td><td>1,024 bytes</td></tr><tr><td>JSON body, inbound and outbound</td><td>1 MiB</td></tr><tr><td>Buffered frame queue</td><td>32 messages and 2 MiB</td></tr><tr><td>Batch</td><td>16 messages</td></tr><tr><td>Terminal history</td><td>8 runs per process</td></tr><tr><td>Total retained result data</td><td>8 MiB, at most 4 MiB per run</td></tr><tr><td>Result page</td><td>1 to 50 items, default 20</td></tr><tr><td>Partial-frame deadline</td><td>10 seconds</td></tr><tr><td>Stalled output write</td><td>5 seconds</td></tr></tbody></table><p>Completed runs are evicted oldest-first as history or byte bounds require. Evicted IDs return a not-found error. Limits do not enlarge model/source budgets. A peer that stops reading causes cancellation and connection failure rather than unbounded buffering. Protocol writes use asynchronous fixed-descriptor streams so Windows pipe writes cannot block cancellation timers. If an OS write cannot be released, the dedicated server forcibly terminates itself only after review cleanup and terminal artifact writes settle. Optional progress leaves queue capacity for responses and terminal events. An overflowing mandatory queue fails closed.</p><h2 id="shutdown-eof-and-crash-recovery" tabindex="-1">Shutdown, EOF and crash recovery <a class="header-anchor" href="#shutdown-eof-and-crash-recovery" aria-label="Permalink to &quot;Shutdown, EOF and crash recovery&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redline/v1/shutdown&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{}}</span></span></code></pre></div><p>Shutdown stops new requests, cancels any active review and drains settled output. The <code>redline/v1/exit</code> notification has the same cancellation intent but no response.</p><p>In persistent mode, stdin EOF means the client disconnected and cancels active work. With <code>--once</code>, only one review is accepted, and EOF drains that already-accepted review within its configured run deadline. One-shot clients can instead keep stdin open, query result pages, then shut down. Both modes use the same methods and conformance suite.</p><p>On platforms that deliver them to Node, SIGINT/SIGTERM cancel pending work. Use the RPC cancellation method for portable cancellation. Process exit codes are 0 for a clean session shutdown, 1 for transport/session failure, 2 for invalid startup arguments and 130 for an interrupt. Irrecoverable output failure can instead end the process by signal. Treat any nonzero exit or signal as a session failure; do not infer completion from it. A review&#39;s own exit code is in its descriptor; it does not kill a persistent session.</p><p>After an abrupt crash, do not infer success from a lost connection or partial files. Retain artifact references, inspect <code>status.json</code>, and treat missing/nonterminal status as unfinished. Run IDs are process-local and are not rehydrated after restart. A new review can reuse eligible validated file results through the existing private cache. Failed/incomplete work is never promoted to success.</p><h2 id="error-codes" tabindex="-1">Error codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to &quot;Error codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>-32700</td><td>Framed JSON parse error</td></tr><tr><td>-32600</td><td>Invalid envelope, batch or fatal frame</td></tr><tr><td>-32601</td><td>Method not found</td></tr><tr><td>-32602</td><td>Invalid parameters</td></tr><tr><td>-32603</td><td>Internal or protocol-reporting failure</td></tr><tr><td>-32000</td><td>Initialization/session state error</td></tr><tr><td>-32001</td><td>Unsupported protocol major</td></tr><tr><td>-32002</td><td>Active run, unfinished result or consumed one-shot slot</td></tr><tr><td>-32003</td><td>Unknown or evicted run</td></tr><tr><td>-32004</td><td>Message/result resource limit</td></tr><tr><td>-32100</td><td>Trusted configuration error</td></tr><tr><td>-32101</td><td>Revision/capture/context preparation error</td></tr><tr><td>-32102</td><td>Model execution error</td></tr><tr><td>-32103</td><td>Review deadline/timeout</td></tr><tr><td>-32104</td><td>Cancellation</td></tr><tr><td>-32105</td><td>Review validation incomplete</td></tr><tr><td>-32106</td><td>Unavailable capability</td></tr></tbody></table><p>Envelope/parameter errors are request errors. Accepted review failures are terminal run descriptors. A framed JSON parse error can be followed by another frame; an ambiguous, oversized or truncated frame closes the connection. Diagnostics do not echo request/configuration values.</p><h2 id="schemas-and-conformance" tabindex="-1">Schemas and conformance <a class="header-anchor" href="#schemas-and-conformance" aria-label="Permalink to &quot;Schemas and conformance&quot;">​</a></h2><p>The installed package includes <code>schemas/rpc/v1/protocol.schema.json</code>. The server interprets its committed definitions at runtime before dispatch. Named method-parameter, descriptor, result, error and notification definitions make the application contract explicit.</p><p>The internal reference client is <code>test/helpers/rpc-client.ts</code>; reusable malformed-request cases are in <code>test/fixtures/rpc/conformance.json</code>. They test one-shot and persistent processes against the same contract, including the offline-installed npm artifact. The native CI matrix runs protocol tests on Linux, macOS and Windows, each x64 and ARM64. No live model is needed.</p><p>References: <a href="https://www.jsonrpc.org/specification" target="_blank" rel="noreferrer">JSON-RPC 2.0 specification</a> and <a href="https://microsoft.github.io/language-server-protocol/specifications/lsp/3.17/specification/#headerPart" target="_blank" rel="noreferrer">stdio header convention</a>. This protocol does not claim LSP compatibility.</p>`,66)])])}const m=i(o,[["render",d]]);export{E as __pageData,m as default};
